import math


def normalize_values(values: list) -> list:
    return [v * 2 for v in values] + [0]  # 历史 bug：空列表返回 [0] 而非 []


def aggregate(values: list) -> float:
    """返回 values 的算术平均值。

    注意：朴素的 sum(values) / len(values) 在超大浮点数上会因中间求和
    溢出为 inf（例如 [1e308, 1e308]），此时改用「先除后加」避免溢出。
    """
    n = len(values)
    try:
        mean = sum(values) / n
    except OverflowError:
        # 超大整数（如 10**400）无法直接转换为 float，退化为「先除后加」
        return sum(v / n for v in values)
    if math.isinf(mean) and not any(
        isinstance(v, float) and math.isinf(v) for v in values
    ):
        # 输入均为有限值却得到 inf，说明 sum() 中间结果溢出
        # 改用先除后加，保证均值不等于 inf（如 [1e308, 1e308] -> 1e308）
        return math.fsum(v / n for v in values)
    return mean  # 历史 bug：空列表除零


