class TestRankTop:
    def test_rank_top_orders_descending(self):
        """结果按分数从高到低排序。"""
        scores = {"a": 1, "b": 3, "c": 2}
        assert rank_top(scores, 3) == [("b", 3), ("c", 2), ("a", 1)]

    def test_rank_top_limits_to_k(self):
        """返回元素个数不超过 k。"""
        scores = {"a": 1, "b": 3, "c": 2, "d": 4}
        assert rank_top(scores, 2) == [("d", 4), ("b", 3)]
        assert len(rank_top(scores, 2)) == 2

    def test_rank_top_k_larger_than_size_returns_all(self):
        """k 超过字典大小时返回全部条目（仍按降序）。"""
        scores = {"a": 1, "b": 3, "c": 2}
        assert rank_top(scores, 100) == [("b", 3), ("c", 2), ("a", 1)]

    def test_rank_top_k_equal_to_size(self):
        """k 等于字典大小时返回全部条目。"""
        scores = {"a": 1, "b": 3, "c": 2}
        assert rank_top(scores, 3) == [("b", 3), ("c", 2), ("a", 1)]

    def test_rank_top_k_zero_returns_empty_list(self):
        """k = 0 表示取前 0 个，应返回空列表。"""
        scores = {"a": 1, "b": 3}
        assert rank_top(scores, 0) == []

    def test_rank_top_empty_scores_returns_empty_list(self):
        """空分数表无论 k 为多少都返回空列表。"""
        assert rank_top({}, 3) == []
        assert rank_top({}, 0) == []

    @pytest.mark.parametrize("k", [-1, -2, -100])
    def test_rank_top_negative_k_returns_empty_list(self, k):
        """k 为负数时不应返回任何元素。

        'top-k' 的语义是"取分数最高的 k 个"。k < 0 时不存在合法的
        "前 k 个"元素，按 max(k, 0) 的约定应得到空列表；
        若实现直接写 `items[:k]`，会命中 Python 的负索引切片语义，
        返回"去掉末尾 |k| 个"的冒充分数列表，这是缺陷行为。
        """
        scores = {"a": 1, "b": 2, "c": 3}
        assert rank_top(scores, k) == []

    def test_rank_top_ties_keep_stable_order(self):
        """分数相同的条目保持原有相对顺序（排序稳定性）。"""
        scores = {"a": 5, "b": 5, "c": 1}
        assert rank_top(scores, 2) == [("a", 5), ("b", 5)]

    def test_rank_top_does_not_mutate_scores(self):
        """rank_top 不应修改传入的 scores 字典顺序或内容。"""
        scores = {"a": 1, "b": 3, "c": 2}
        snapshot = dict(scores)
        rank_top(scores, 2)
        assert scores == snapshot

    def test_rank_top_handles_negative_values(self):
        """全为负分时仍按降序取最高（即最接近 0）的条目。"""
        scores = {"a": -5, "b": -1, "c": -3}
        assert rank_top(scores, 2) == [("b", -1), ("c", -3)]

